/**
 * The Living Manifesto v0.4 — one-file GitHub deployment (iPhone compatible).
 * Keeps the existing Cloudflare Worker, D1 database and credentials unchanged.
 * Build command: node deploy.mjs; Deploy command: npx wrangler deploy.
 * Only public application code/assets are embedded. Never put secrets here.
 */
import {mkdir,writeFile} from 'node:fs/promises';
import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {Buffer} from 'node:buffer';
const entries =
[["_worker.js","","c205141579fc9fbcd362582768cf392f806f72c9dc753a0e700d91912642b1b1"],["index.html","","618e1ebefc1452fb85064b78288366f41d9067e90ce3a5b3de1f26d17a12b68a"],["styles.css","","5d84b97d20efdb7ae140b41a3e36dadc96e738b0048886f5aedcf3bb373359b6"],["app.js","","162cc4d5dd6dea6908e25fbab90d2a9fbc07d2ed5f3177d2bff66c614f1d293a"],["manifest.webmanifest","","7bf0277d73f618c7c76e7a27dba501effbe9ada344a5316054a0a3278353dd87"],["service-worker.js","","fd5c497774ed875228c3ad0a45f516506d2a67ccaa92fc29eeeeb6fadd615129"],["icon-180.png","","9f2ed78e67796b87e56a32f4b974c8b42d7dbc7d2bfe137dc2a8e09d84fc9cb9"],["icon-192.png","","9ae985585f36218e4f3634c480b0d02954d46e62df72f280b2c873b57495815b"],["icon-512.png","","d33a7df296eeff7be392d8b903ac5fff1c6f961de2af3291439cd255fe0af3f0"],["_headers","","377c696f6ef110d90a5215dcde8f78f91364cdea3840716dfb95655128e2008f"]];

await mkdir('dist',{recursive:true});
for(const [name,gz,sha] of entries){
 const contents=gunzipSync(Buffer.from(gz,'base64'));
 if(createHash('sha256').update(contents).digest('hex')!==sha)throw Error('Integrity verification failed: '+name);
 await writeFile('dist/'+name,contents);
 console.log('Prepared '+name+' ('+contents.byteLength+' bytes)');
}
console.log('Living Manifesto v0.4.0 ready — article extraction and verified ChatGPT analysis.');
